mapper.select:
SELECT resource_ref FROM audit_event a WHERE audit_id=#{auditId} AND project_id=#{projectId} AND subject_id=#{userId}
  AND action='source.upload.completion.requested' AND result='SUCCESS' AND request_id=#{requestId} AND trace_id=#{requestId}
  AND schema_version='1.0.0' AND schema_manifest_sha256=#{manifest} AND created_by=#{userId} AND classification=#{classification} FOR UPDATE

mapper.update:
UPDATE outbox_delivery SET status='DELIVERING',attempt_no=attempt_no+1,lease_owner=#{leaseOwner},lease_until=#{leaseUntil},
  lease_generation=lease_generation+1,revision=revision+1,updated_at=#{now}
WHERE event_id=#{eventId} AND consumer_id=#{consumerId} AND created_by=#{userId}
  AND revision=#{revision} AND lease_generation=#{generation} AND attempt_no < 6 AND next_attempt_at <= #{now}
  AND ((status='PENDING' AND lease_owner IS NULL AND lease_until IS NULL)
    OR (status='DELIVERING' AND lease_owner IS NOT NULL AND lease_until <= #{now}))

UPDATE outbox_delivery SET lease_until=#{leaseUntil},revision=revision+1,updated_at=#{now}
WHERE event_id=#{eventId} AND consumer_id=#{consumerId} AND created_by=#{userId} AND status='DELIVERING'
  AND lease_owner=#{leaseOwner} AND lease_generation=#{generation} AND revision=#{revision}
  AND attempt_no=#{attempt} AND lease_until > #{now}

UPDATE operation_record SET state='COMPLETED',http_status=200,response_ref=#{response},revision=revision+1,updated_at=UTC_TIMESTAMP(6)
WHERE operation_id=#{operationId} AND subject_id=#{userId} AND created_by=#{userId} AND operation_name='KN-02'
  AND idempotency_key=#{key} AND request_sha256=#{requestSha256} AND target_id=#{uploadId}
  AND state='PROCESSING' AND revision=1 AND http_status IS NULL AND response_ref IS NULL AND error_code IS NULL
  AND schema_version='1.0.0' AND schema_manifest_sha256=#{manifest}

