UPDATE upload_item SET received_size=#{receivedSize},status='UPLOADING',revision=revision+1,updated_at=UTC_TIMESTAMP(6)
WHERE upload_id=#{uploadId} AND created_by=#{userId} AND revision=#{revision}
  AND received_size=#{previousSize} AND status IN ('PENDING','UPLOADING') AND #{receivedSize}<=expected_size

